284	function parseAgent(filePath) {
285	  try {
286	    const content = fs.readFileSync(filePath, 'utf-8');
287	    const { data, content: body } = matter(content);
288	    const stats = fs.statSync(filePath);
289	    return {
290	      filename: path.basename(filePath, '.md'),
291	      path: filePath,
292	      frontmatter: data,
293	      name: data.name || path.basename(filePath, '.md'),
294	      description: data.description || '',
295	      model: data.model || '',
296	      tools: data.tools || '',
297	      body: body.trim(),
298	      raw: content,
299	      updatedAt: stats.mtime.toISOString(),
300	    };
301	  } catch (e) {
302	    return null;
303	  }
304	}
