453	function discoverProjects(dirs) {
454	  const projects = [];
455	  for (const dir of dirs) {
456	    const resolved = dir.replace(/^~/, HOME);
457	    if (!fs.existsSync(resolved)) continue;
458	    try {
459	      const entries = fs.readdirSync(resolved, { withFileTypes: true });
460	      for (const entry of entries) {
461	        if (!entry.isDirectory()) continue;
462	        if (entry.name.startsWith('.') || entry.name === 'node_modules') continue;
463	        const projectPath = path.join(resolved, entry.name);
464	        const hasClaudeDir = fs.existsSync(path.join(projectPath, '.claude'));
465	        const hasClaudeMd = fs.existsSync(path.join(projectPath, 'CLAUDE.md'));
466	        const hasPackageJson = fs.existsSync(path.join(projectPath, 'package.json'));
467	        const hasPubspec = fs.existsSync(path.join(projectPath, 'pubspec.yaml'));
468	        if (hasClaudeDir || hasClaudeMd || hasPackageJson || hasPubspec) {
469	          const agents = listAgents(path.join(projectPath, '.claude', 'agents'));
470	          const commands = listMdFiles(path.join(projectPath, '.claude', 'commands'));
471	          const rules = listMdFiles(path.join(projectPath, '.claude', 'rules'));
472	          projects.push({
473	            id: Buffer.from(projectPath).toString('base64url'),
474	            name: entry.name,
475	            path: projectPath,
476	            displayPath: projectPath.replace(HOME, '~'),
477	            hasClaudeDir,
478	            hasClaudeMd,
479	            agentCount: agents.length,
480	            commandCount: commands.length,
481	            ruleCount: rules.length,
482	            agents,
483	            commands: commands.map(c => c.name),
484	            rules: rules.map(r => r.name),
485	          });
486	        }
487	      }
488	    } catch {}
489	  }
490	  return projects;
491	}
