775	  if (typeof targetPath !== 'string' || targetPath.includes('\0')) {
776	    return res.status(400).json({ error: 'Invalid path' });
777	  }
778	  targetPath = path.resolve(targetPath);
779	  // Restrict browsing to home directory tree
780	  if (!targetPath.startsWith(HOME)) {
781	    return res.status(403).json({ error: 'Cannot browse outside home directory' });
782	  }
783	
784	  try {
785	    if (!fs.existsSync(targetPath)) {
786	      return res.status(404).json({ error: 'Path not found' });
787	    }
788	    const stat = fs.statSync(targetPath);
789	    if (!stat.isDirectory()) {
790	      return res.status(400).json({ error: 'Not a directory' });
791	    }
792	
793	    const entries = fs.readdirSync(targetPath, { withFileTypes: true });
794	    const dirs = entries
795	      .filter(e => e.isDirectory() && !e.name.startsWith('.') && e.name !== 'node_modules' && e.name !== '__pycache__')
796	      .map(e => ({
797	        name: e.name,
798	        path: path.join(targetPath, e.name),
799	        displayPath: path.join(targetPath, e.name).replace(HOME, '~'),
800	        hasProjects: false,
801	      }))
802	      .sort((a, b) => a.name.localeCompare(b.name));
803	
804	    for (const dir of dirs) {
805	      try {
806	        const sub = fs.readdirSync(dir.path, { withFileTypes: true });
807	        dir.hasProjects = sub.some(s =>
808	          s.isDirectory() && (
809	            fs.existsSync(path.join(dir.path, s.name, '.claude')) ||
810	            fs.existsSync(path.join(dir.path, s.name, 'CLAUDE.md')) ||
811	            fs.existsSync(path.join(dir.path, s.name, 'package.json')) ||
812	            fs.existsSync(path.join(dir.path, s.name, 'pubspec.yaml'))
813	          )
814	        );
815	      } catch {}
816	    }
817	
818	    const parts = targetPath.split(path.sep).filter(Boolean);
819	    const breadcrumbs = parts.map((part, i) => ({
820	      name: i === 0 && targetPath.startsWith(HOME) ? '~' : part,
821	      path: path.sep + parts.slice(0, i + 1).join(path.sep),
822	    }));
823	
824	    if (targetPath.startsWith(HOME)) {
825	      const homeIndex = HOME.split(path.sep).filter(Boolean).length - 1;
826	      breadcrumbs.splice(0, homeIndex + 1, { name: '~', path: HOME });
827	    }
828	
829	    res.json({
830	      current: targetPath,
831	      displayPath: targetPath.replace(HOME, '~'),
832	      parent: path.dirname(targetPath) !== targetPath ? path.dirname(targetPath) : null,
833	      breadcrumbs,
834	      directories: dirs,
835	    });
836	  } catch (e) {
