1775	// Topological sort helper
1776	function topoSort(nodes, edges) {
1777	  const inDegree = {};
1778	  const adj = {};
1779	  for (const n of nodes) { inDegree[n.id] = 0; adj[n.id] = []; }
1780	  for (const e of edges) {
1781	    adj[e.source].push(e.target);
1782	    inDegree[e.target] = (inDegree[e.target] || 0) + 1;
1783	  }
1784	  const queue = nodes.filter(n => inDegree[n.id] === 0).map(n => n.id);
1785	  const order = [];
1786	  while (queue.length) {
1787	    const id = queue.shift();
1788	    order.push(id);
1789	    for (const next of adj[id]) {
1790	      inDegree[next]--;
1791	      if (inDegree[next] === 0) queue.push(next);
1792	    }
1793	  }
1794	  return order;
1795	}
