1797	// Level-based grouping for parallel execution
1798	function topoLevels(nodes, edges) {
1799	  const inDegree = {};
1800	  const adj = {};
1801	  for (const n of nodes) { inDegree[n.id] = 0; adj[n.id] = []; }
1802	  for (const e of edges) {
1803	    adj[e.source] = adj[e.source] || [];
1804	    adj[e.source].push(e.target);
1805	    inDegree[e.target] = (inDegree[e.target] || 0) + 1;
1806	  }
1807	  const levels = [];
1808	  let queue = nodes.filter(n => inDegree[n.id] === 0).map(n => n.id);
1809	  while (queue.length) {
1810	    levels.push([...queue]);
1811	    const nextQueue = [];
1812	    for (const id of queue) {
1813	      for (const next of (adj[id] || [])) {
1814	        inDegree[next]--;
1815	        if (inDegree[next] === 0) nextQueue.push(next);
1816	      }
1817	    }
1818	    queue = nextQueue;
1819	  }
1820	  return levels;
1821	}
