61	// Token encryption — derived from a stable machine-local key
62	function getMachineKey() {
63	  // Uses hostname + home dir as a weak-but-stable key derivation
64	  // For production: store a real secret in env var or OS keychain
65	  const seed = `${os.hostname()}-${os.homedir()}-claude-hub-backup-v1`;
66	  return crypto.createHash('sha256').update(seed).digest();
67	}
