69	function encryptToken(plaintext) {
70	  if (!plaintext) return '';
71	  const key = getMachineKey();
72	  const iv = crypto.randomBytes(12);
73	  const cipher = crypto.createCipheriv('aes-256-gcm', key, iv);
74	  const enc = Buffer.concat([cipher.update(plaintext, 'utf8'), cipher.final()]);
75	  const tag = cipher.getAuthTag();
76	  return `${iv.toString('base64')}:${tag.toString('base64')}:${enc.toString('base64')}`;
77	}
78	
79	function decryptToken(ciphertext) {
80	  if (!ciphertext) return '';
81	  try {
82	    const [ivB64, tagB64, encB64] = ciphertext.split(':');
83	    const key = getMachineKey();
84	    const iv = Buffer.from(ivB64, 'base64');
85	    const tag = Buffer.from(tagB64, 'base64');
86	    const enc = Buffer.from(encB64, 'base64');
87	    const decipher = crypto.createDecipheriv('aes-256-gcm', key, iv);
88	    decipher.setAuthTag(tag);
89	    return Buffer.concat([decipher.update(enc), decipher.final()]).toString('utf8');
90	  } catch {
91	    return '';
92	  }
93	}
