170	/**
171	 * Classify a git push / clone / auth failure into a stable error code.
172	 * Codes: REPO_NOT_FOUND | AUTH_INVALID | PERMISSION_DENIED | NETWORK |
173	 *        NON_FAST_FORWARD | LFS_REQUIRED | UNKNOWN
174	 */
175	function classifyGitError(rawMessage) {
176	  const msg = (rawMessage || '').toLowerCase();
177	
178	  if (/\b404\b|repository not found|not found\.?\s*$/.test(msg)) {
179	    return {
180	      code: 'REPO_NOT_FOUND',
181	      title: 'Repository does not exist',
182	      detail: 'The backup repo URL points to a repository that has not been created yet.',
183	      fix: 'Create the repo on GitHub, or click "Create Repo" to have us create it for you.',
184	      actions: ['create_remote', 'change_repo'],
185	    };
186	  }
187	  if (/\b401\b|bad credentials|authentication failed|could not read username/.test(msg)) {
188	    return {
189	      code: 'AUTH_INVALID',
190	      title: 'GitHub token is invalid or expired',
191	      detail: 'The stored Personal Access Token was rejected by GitHub.',
192	      fix: 'Generate a new fine-grained PAT with "Contents: Read and Write" scope and reconnect.',
193	      actions: ['reconnect'],
194	    };
195	  }
196	  if (/\b403\b|permission denied|forbidden|write access.*not granted|requested url returned error: 403/.test(msg)) {
197	    return {
198	      code: 'PERMISSION_DENIED',
199	      title: 'Token lacks write permission',
200	      detail: 'The token is valid but does not have write access to this repository.',
201	      fix: 'Regenerate the PAT with "Contents: Read and Write" scope for this repo, then reconnect.',
202	      actions: ['reconnect', 'verify_remote'],
203	    };
204	  }
205	  if (/non-fast-forward|fetch first|rejected.*fetch|updates were rejected/.test(msg)) {
206	    return {
207	      code: 'NON_FAST_FORWARD',
208	      title: 'Remote has diverged',
209	      detail: 'The remote branch has commits that are not in your local backup.',
210	      fix: 'Resolve manually — this usually means the remote was edited outside the backup system.',
211	      actions: ['retry_push'],
212	    };
213	  }
214	  if (/lfs|large file/.test(msg)) {
215	    return {
216	      code: 'LFS_REQUIRED',
217	      title: 'Large file detected',
218	      detail: 'A file exceeds GitHub\'s 100 MB limit and requires Git LFS.',
219	      fix: 'Exclude large files or enable Git LFS on the backup repo.',
220	      actions: [],
221	    };
222	  }
223	  if (/could not resolve host|network|timeout|getaddrinfo|econnrefused|econnreset/.test(msg)) {
224	    return {
225	      code: 'NETWORK',
226	      title: 'Network unreachable',
227	      detail: 'Could not reach GitHub. Your commits are safe locally and will push when connectivity returns.',
228	      fix: 'Check your internet connection, then retry.',
229	      actions: ['retry_push'],
230	    };
231	  }
232	  return {
233	    code: 'UNKNOWN',
234	    title: 'Push failed',
235	    detail: rawMessage ? rawMessage.split('\n')[0].slice(0, 200) : 'Unknown error',
236	    fix: 'Review the error detail and check the backup logs.',
237	    actions: ['retry_push', 'verify_remote'],
238	  };
239	}
