245	function parseRepoUrl(repoUrl) {
246	  try {
247	    const url = new URL(repoUrl);
248	    if (url.hostname !== 'github.com') return null;
249	    const parts = url.pathname.replace(/^\/+/, '').replace(/\.git$/, '').split('/');
250	    if (parts.length < 2) return null;
251	    return { owner: parts[0], name: parts[1] };
252	  } catch {
253	    return null;
254	  }
255	}
