257	function githubRequest({ method, pathname, token, body }) {
258	  return new Promise((resolve) => {
259	    const data = body ? JSON.stringify(body) : null;
260	    const req = https.request({
261	      hostname: 'api.github.com',
262	      path: pathname,
263	      method,
264	      headers: {
265	        'Authorization': `Bearer ${token}`,
266	        'Accept': 'application/vnd.github+json',
267	        'X-GitHub-Api-Version': '2022-11-28',
268	        'User-Agent': 'Polyglot-Backup/1.0',
269	        ...(data ? { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(data) } : {}),
270	      },
271	      timeout: 10000,
272	    }, (res) => {
273	      let chunks = '';
274	      res.on('data', (c) => chunks += c);
275	      res.on('end', () => {
276	        let parsed = null;
277	        try { parsed = chunks ? JSON.parse(chunks) : null; } catch {}
278	        resolve({ status: res.statusCode || 0, body: parsed, headers: res.headers });
279	      });
280	    });
281	    req.on('error', (err) => resolve({ status: 0, body: null, error: err.message }));
282	    req.on('timeout', () => { req.destroy(); resolve({ status: 0, body: null, error: 'timeout' }); });
283	    if (data) req.write(data);
284	    req.end();
285	  });
286	}
