95	      .readFileSync(filePath, 'utf-8')
96	      .split('\n')
97	      .filter(Boolean)
98	      .map((l) => { try { return JSON.parse(l); } catch { return null; } })
99	      .filter(Boolean);
100	  } catch {
101	    return [];
102	  }
