1	/**
2	 * Experience Module — computes per-agent experience level, years of
3	 * experience, and skill vectors from multiple signals:
4	 *
5	 *   1. Training depth   → word count of the agent's .md file
6	 *   2. Tenure           → days since hiredAt
7	 *   3. Runs             → count from agent-runs.json
8	 *   4. Successes        → success_rate * run count
9	 *   5. Patterns         → patterns/good/*.md files where this agent is cited
10	 *   6. Antipatterns     → lessons/bugs.jsonl entries where agent_that_shipped matches
11	 *
12	 * The formula is deterministic, transparent, and tunable via
13	 * ~/.claude/org/experience-weights.json (optional override).
14	 *
15	 * YoE (years of experience) is scaled to feel human:
16	 *   ~10 KB of training content = 1 year
17	 *   ~20 runs = 1 year
18	 *   ~90 days of tenure = 1 year
19	 *
20	 * Levels map to human career titles from Trainee (0) to Distinguished (8).
21	 */
22	
23	const fs = require('fs');
24	const path = require('path');
25	const os = require('os');
26	
27	const HOME = os.homedir();
28	const CLAUDE_DIR = path.join(HOME, '.claude');
29	const AGENTS_DIR = path.join(CLAUDE_DIR, 'agents');
30	const MEMORY_DIR = path.join(CLAUDE_DIR, 'memory');
31	const WEIGHTS_PATH = path.join(CLAUDE_DIR, 'org', 'experience-weights.json');
32	
33	// Path to Polyglot's run-tracking files (caller-controlled in tests)
34	const POLYGLOT_ROOT = path.resolve(__dirname, '..');
35	const AGENT_RUNS_PATH = path.join(POLYGLOT_ROOT, 'agent-runs.json');
36	
37	// ──────────────────────────────────────────────────────────────────────────
38	//  Weights — tunable via ~/.claude/org/experience-weights.json
39	// ──────────────────────────────────────────────────────────────────────────
40	
41	const DEFAULT_WEIGHTS = {
42	  trainingKbPerYear: 10,   // 10 KB of .md content = 1 YoE
43	  runsPerYear: 20,         // 20 runs = 1 YoE
44	  daysPerYear: 90,         // 90 days tenure = 1 YoE
45	  patternWeight: 0.5,      // each pattern contributed = +0.5 YoE
46	  antipatternPenalty: 0.3, // each antipattern triggered = -0.3 YoE
47	  successBonus: 0.5,       // high success rate bonus (max +0.5 YoE)
48	};
49	
50	function loadWeights() {
51	  try {
52	    if (fs.existsSync(WEIGHTS_PATH)) {
53	      return { ...DEFAULT_WEIGHTS, ...JSON.parse(fs.readFileSync(WEIGHTS_PATH, 'utf-8')) };
54	    }
55	  } catch {}
56	  return { ...DEFAULT_WEIGHTS };
57	}
58	
59	// ──────────────────────────────────────────────────────────────────────────
60	//  Levels
61	// ──────────────────────────────────────────────────────────────────────────
62	
63	const LEVEL_THRESHOLDS = [
64	  { level: 0, title: 'Trainee',       minYoE: 0,    maxYoE: 1,  color: '#9ca3af', canMentor: false, canShipProd: false },
65	  { level: 1, title: 'Junior',        minYoE: 1,    maxYoE: 3,  color: '#6ee7b7', canMentor: false, canShipProd: false },
66	  { level: 2, title: 'Mid',           minYoE: 3,    maxYoE: 5,  color: '#34d399', canMentor: false, canShipProd: true },
67	  { level: 3, title: 'Senior',        minYoE: 5,    maxYoE: 8,  color: '#10b981', canMentor: true,  canShipProd: true },
68	  { level: 4, title: 'Lead',          minYoE: 8,    maxYoE: 12, color: '#3b82f6', canMentor: true,  canShipProd: true },
69	  { level: 5, title: 'Principal',     minYoE: 12,   maxYoE: 18, color: '#8b5cf6', canMentor: true,  canShipProd: true },
70	  { level: 6, title: 'Staff',         minYoE: 18,   maxYoE: 25, color: '#a855f7', canMentor: true,  canShipProd: true },
71	  { level: 7, title: 'Distinguished', minYoE: 25,   maxYoE: 40, color: '#f59e0b', canMentor: true,  canShipProd: true },
72	  { level: 8, title: 'Fellow',        minYoE: 40,   maxYoE: Infinity, color: '#eab308', canMentor: true, canShipProd: true },
73	];
74	
75	function levelForYoE(yoe) {
76	  for (let i = LEVEL_THRESHOLDS.length - 1; i >= 0; i--) {
77	    if (yoe >= LEVEL_THRESHOLDS[i].minYoE) return LEVEL_THRESHOLDS[i];
78	  }
79	  return LEVEL_THRESHOLDS[0];
80	}
81	
82	// ──────────────────────────────────────────────────────────────────────────
83	//  Signal collection
84	// ──────────────────────────────────────────────────────────────────────────
85	
86	function readAgentFileStats(agentId) {
87	  const mdPath = path.join(AGENTS_DIR, `${agentId}.md`);
88	  if (!fs.existsSync(mdPath)) {
89	    return { sizeBytes: 0, words: 0, lines: 0, exists: false };
90	  }
91	  try {
92	    const content = fs.readFileSync(mdPath, 'utf-8');
93	    const sizeBytes = Buffer.byteLength(content, 'utf-8');
94	    const words = content.split(/\s+/).filter(Boolean).length;
95	    const lines = content.split(/\n/).length;
96	    return { sizeBytes, words, lines, exists: true };
97	  } catch {
98	    return { sizeBytes: 0, words: 0, lines: 0, exists: false };
99	  }
100	}
101	
102	function loadAgentRuns() {
103	  try {
104	    if (!fs.existsSync(AGENT_RUNS_PATH)) return [];
105	    const raw = JSON.parse(fs.readFileSync(AGENT_RUNS_PATH, 'utf-8'));
106	    return Array.isArray(raw) ? raw : [];
107	  } catch {
108	    return [];
109	  }
110	}
111	
112	function computeRunStats(agentId, allRuns) {
113	  const runs = allRuns.filter((r) => r.agentName === agentId);
114	  const total = runs.length;
115	  const successes = runs.filter((r) => r.status === 'success').length;
116	  const failures = runs.filter((r) => r.status === 'failed' || r.status === 'error').length;
117	  const successRate = total > 0 ? successes / total : 0;
118	  const totalDuration = runs.reduce((s, r) => s + (r.duration || 0), 0);
119	  const avgDurationMs = total > 0 ? totalDuration / total : 0;
120	  const lastRunAt = runs.length > 0
121	    ? runs.map((r) => r.timestamp).sort().slice(-1)[0]
122	    : null;
123	  return { totalRuns: total, successRuns: successes, failedRuns: failures, successRate, avgDurationMs, lastRunAt };
124	}
125	
126	function countPatternsContributed(agentId) {
127	  const goodDir = path.join(MEMORY_DIR, 'patterns', 'good');
128	  if (!fs.existsSync(goodDir)) return 0;
129	  let count = 0;
130	  const files = fs.readdirSync(goodDir).filter((f) => f.endsWith('.md'));
131	  const needle = new RegExp(`\\b${agentId}\\b`, 'i');
132	  for (const f of files) {
133	    try {
134	      const content = fs.readFileSync(path.join(goodDir, f), 'utf-8');
135	      // Look in source/contributor blocks
136	      if (/source:|contributor:|author:/i.test(content) && needle.test(content)) {
137	        count++;
138	      }
139	    } catch {}
140	  }
141	  return count;
142	}
143	
144	function countAntipatternsTriggered(agentId) {
145	  const bugsPath = path.join(MEMORY_DIR, 'lessons', 'bugs.jsonl');
146	  if (!fs.existsSync(bugsPath)) return 0;
147	  try {
148	    const lines = fs.readFileSync(bugsPath, 'utf-8').split('\n').filter(Boolean);
149	    let count = 0;
150	    for (const line of lines) {
151	      try {
152	        const entry = JSON.parse(line);
153	        if (entry.agent_that_shipped === agentId || entry.agent === agentId) count++;
154	      } catch {}
155	    }
156	    return count;
157	  } catch {
158	    return 0;
159	  }
160	}
161	
162	// ──────────────────────────────────────────────────────────────────────────
163	//  Skill vector — keyword scan of agent .md body
164	// ──────────────────────────────────────────────────────────────────────────
165	
166	const SKILL_KEYWORDS = {
167	  react:        ['react', 'jsx', 'tsx', 'hooks', 'useeffect', 'usestate'],
168	  typescript:   ['typescript', 'tsc', 'strict mode', 'interface', 'generic'],
169	  nextjs:       ['next.js', 'nextjs', 'app router', 'server component', 'route handler'],
170	  supabase:     ['supabase', 'rls', 'row level security', 'postgres'],
171	  shopify:      ['shopify', 'polaris', 'admin api', 'storefront', 'embedded app'],
172	  billing:      ['stripe', 'dodo', 'billing', 'subscription', 'payment', 'checkout'],
173	  auth:         ['auth', 'oauth', 'session', 'jwt', 'magic link', 'otp'],
174	  testing:      ['test', 'vitest', 'jest', 'playwright', 'e2e', 'unit test'],
175	  design:       ['figma', 'design system', 'tailwind', 'shadcn', 'polaris'],
176	  seo:          ['seo', 'meta tags', 'sitemap', 'schema.org', 'core web vitals'],
177	  deployment:   ['deploy', 'railway', 'vercel', 'docker', 'ci/cd'],
178	  ai:           ['llm', 'prompt', 'streaming', 'tool use', 'anthropic', 'openai'],
179	  marketing:    ['landing page', 'copy', 'funnel', 'conversion', 'email campaign'],
180	  research:     ['validation', 'icp', 'persona', 'interview', 'market size'],
181	  debugging:    ['bug', 'stack trace', 'root cause', 'regression', 'incident'],
182	  architecture: ['architecture', 'data model', 'api design', 'scalab', 'system design'],
183	};
184	
185	function computeSkillVector(agentId) {
186	  const mdPath = path.join(AGENTS_DIR, `${agentId}.md`);
187	  if (!fs.existsSync(mdPath)) return {};
188	  try {
189	    const content = fs.readFileSync(mdPath, 'utf-8').toLowerCase();
190	    const skills = {};
191	    for (const [skill, keywords] of Object.entries(SKILL_KEYWORDS)) {
192	      let hits = 0;
193	      for (const kw of keywords) {
194	        const re = new RegExp(`\\b${kw.replace(/[.+*?^${}()|[\]\\]/g, '\\$&')}\\b`, 'g');
195	        const matches = content.match(re);
196	        if (matches) hits += matches.length;
197	      }
198	      if (hits > 0) {
199	        // Normalize: log-scale so a few hits ≈ 0.3, many hits ≈ 0.9
200	        const score = Math.min(1, Math.log10(hits + 1) / Math.log10(50));
201	        skills[skill] = { score: Math.round(score * 100) / 100, hits };
202	      }
203	    }
204	    return skills;
205	  } catch {
206	    return {};
207	  }
208	}
209	
210	function identifyWeaknesses(skills, threshold = 0.3) {
211	  return Object.entries(skills)
212	    .filter(([, data]) => data.score < threshold)
213	    .map(([skill]) => skill);
214	}
215	
216	// ──────────────────────────────────────────────────────────────────────────
217	//  Experience computation
218	// ──────────────────────────────────────────────────────────────────────────
219	
220	/**
221	 * Compute a full experience profile for one agent.
222	 *
223	 * @param {object} registryRecord — from ~/.claude/org/registry.json
224	 * @param {array}  allRuns        — from agent-runs.json (pass once for all agents)
225	 * @returns {object} Full experience profile to merge back into registry
226	 */
227	function computeExperience(registryRecord, allRuns) {
228	  const weights = loadWeights();
229	  const agentId = registryRecord.id;
230	  const hiredAt = registryRecord.hiredAt ? new Date(registryRecord.hiredAt) : new Date();
231	  const ageDays = Math.max(0, (Date.now() - hiredAt.getTime()) / (1000 * 60 * 60 * 24));
232	
233	  // 1. Training depth
234	  const fileStats = readAgentFileStats(agentId);
235	  const fileKb = fileStats.sizeBytes / 1024;
236	
237	  // 2. Run stats
238	  const runStats = computeRunStats(agentId, allRuns);
239	
240	  // 3. Pattern contributions
241	  const patternsContributed = countPatternsContributed(agentId);
242	
243	  // 4. Antipatterns triggered
244	  const antipatternsTriggered = countAntipatternsTriggered(agentId);
245	
246	  // 5. Compute YoE
247	  const yoeTraining = fileKb / weights.trainingKbPerYear;
248	  const yoeRuns = runStats.totalRuns / weights.runsPerYear;
249	  const yoeTenure = ageDays / weights.daysPerYear;
250	  const yoePatterns = patternsContributed * weights.patternWeight;
251	  const yoeSuccess = runStats.successRate * weights.successBonus;
252	  const yoeAntipatterns = -antipatternsTriggered * weights.antipatternPenalty;
253	
254	  const yearsOfExperience = Math.max(
255	    0,
256	    yoeTraining + yoeRuns + yoeTenure + yoePatterns + yoeSuccess + yoeAntipatterns
257	  );
258	
259	  // 6. Level from YoE
260	  const levelInfo = levelForYoE(yearsOfExperience);
261	
