2306	function computeLineDiff(before, after) {
2307	  const oldLines = (before || '').split('\n');
2308	  const newLines = (after || '').split('\n');
2309	  const hunks = [];
2310	  const maxLen = Math.max(oldLines.length, newLines.length);
2311	  let i = 0;
2312	  while (i < maxLen) {
2313	    // Skip identical lines
2314	    if (i < oldLines.length && i < newLines.length && oldLines[i] === newLines[i]) { i++; continue; }
2315	    // Start of a changed region
2316	    const hunkStart = i;
2317	    const removed = [];
2318	    const added = [];
2319	    // Collect contiguous changed lines (simple sequential diff)
2320	    while (i < maxLen && !(i < oldLines.length && i < newLines.length && oldLines[i] === newLines[i])) {
2321	      if (i < oldLines.length && (i >= newLines.length || oldLines[i] !== newLines[i])) {
2322	        removed.push(oldLines[i]);
2323	      }
2324	      if (i < newLines.length && (i >= oldLines.length || oldLines[i] !== newLines[i])) {
2325	        added.push(newLines[i]);
2326	      }
2327	      i++;
2328	    }
2329	    if (removed.length || added.length) {
2330	      hunks.push({ line: hunkStart + 1, removed, added });
2331	    }
2332	  }
2333	  return hunks;
2334	}
